ImageProcess::ImageProcess() {}


/**
 * @brief 裁剪灰度图 → 二值图（OTSU + 5x5 闭运算）
 * @param src_img 输入 裁剪灰度 图像（通常为 320x130）
 * @return        OTSU 二值化 + 闭运算后的灰度二值图
 * @sample        cv::Mat bin = ip.processImage(rgb_img);
 * @note          阈值参数 100 仅作为 cv::THRESH_OTSU 不参考的占位，OTSU 自动估算
 */
cv::Mat ImageProcess::processImage(const cv::Mat &src_img)
{
    cv::Mat result_img;
    cv::threshold(src_img, result_img, 100, 255, cv::THRESH_OTSU);
    cv::morphologyEx(result_img, result_img, cv::MORPH_CLOSE, kernel);
    return result_img;
}





