cv::Mat ImageProcess::image_correction(cv::Mat raw )//src输入图像  dst输出图像
{
    int i,j;
    cv::Mat bird(ROI_H, COLSIMAGE, CV_8UC1);
    for (j=0;j< ROI_H;j++)
        for (i=0;i<COLSIMAGE;i++)
            bird.at<uchar>(j, i) = raw.at<uchar>(Array_forward_bird_row[j*COLSIMAGE+i], Array_forward_bird_col[j*COLSIMAGE+i]);
    return bird;
}


/**
 * @brief 高光抑制（调试用，正常巡线不调用）
 * @param src BGR 图像
 * @return    去高光后的 BGR 图像
 * @note      算力较大，建议仅在反光严重场地下开启
 */
cv::Mat ImageProcess::matilluminationChange(cv::Mat src)
{
    cv::Mat gray, threshmat, dst;
    cv::cvtColor(src, gray, cv::COLOR_BGR2GRAY);
    cv::equalizeHist(gray, gray);

    /* 大于 210 的视为高光区 */
    cv::threshold(gray, threshmat, 210, 255, cv::THRESH_BINARY);

    /* 高光区轮廓 + 矩形包围盒填白构造 mask */
    std::vector<std::vector<cv::Point>> contours;
    cv::findContours(threshmat, contours, cv::RETR_EXTERNAL, cv::CHAIN_APPROX_SIMPLE);

    cv::Mat mask = cv::Mat::zeros(src.size(), CV_8UC1);
    for (size_t i = 0; i < contours.size(); ++i)
    {
        cv::Rect rect = cv::boundingRect(contours[i]);
        cv::rectangle(mask, rect, cv::Scalar(255), -1);
    }

    cv::illuminationChange(src, mask, dst, 1.0f, 0.1f);
    return dst;
}
